window.CS50KZ_SQLCHECKS = Object.assign(window.CS50KZ_SQLCHECKS || {}, {
 "sql1-moneyball": {
  "db": "kpl",
  "note": "Бұл - сайттың өз жаттығуы, ресми Moneyball тапсырмасы емес: «Қазақстан Премьер-лигасы» үлгісіндегі ойдан шығарылған футбол дерекқоры (kpl.db: players, teams, performances, salaries; 2021-2024 маусымдары). Бағандар: G - ойналған матчтар, SH - соққылар, SOT - қақпаға соққылар, GL - голдар, AST - голдық пас, YC - сары карточкалар; salary - теңгемен. Әр сұрауды бөлек жазыңыз. Жолдар жиыны дұрыс болса, тексеруші өткізеді (ORDER BY бар тапсырмаларда реті де тексеріледі).",
  "tasks": [
   {
    "f": "1.sql",
    "t": "Жыл бойынша ойыншылардың орташа жалақысын табыңыз. Жылдар кему ретімен. Жалақыны екі таңбаға дейін дөңгелектеп, бағанды «average salary» деп атаңыз. Екі баған: жыл және орташа жалақы.",
    "ref": "SELECT \"year\", ROUND(AVG(\"salary\"), 2) AS \"average salary\" FROM \"salaries\" GROUP BY \"year\" ORDER BY \"year\" DESC;"
   },
   {
    "f": "2.sql",
    "t": "Бауыржан Омаровтың жалақы тарихын табыңыз (жылдар кему ретімен). Екі баған: жыл және жалақы.",
    "ref": "SELECT \"year\", \"salary\" FROM \"salaries\" WHERE \"player_id\" = (SELECT \"id\" FROM \"players\" WHERE \"first_name\" = 'Бауыржан' AND \"last_name\" = 'Омаров') ORDER BY \"year\" DESC;"
   },
   {
    "f": "3.sql",
    "t": "Ренат Ахметовтың гол тарихын табыңыз (жылдар кему ретімен). Екі «Ренат Ахметов» бар: біз іздегені 1995 жылы туған. Екі баған: жыл және голдар (GL).",
    "ref": "SELECT \"year\", \"GL\" FROM \"performances\" WHERE \"player_id\" = (SELECT \"id\" FROM \"players\" WHERE \"first_name\" = 'Ренат' AND \"last_name\" = 'Ахметов' AND \"birth_year\" = 1995) ORDER BY \"year\" DESC;"
   },
   {
    "f": "4.sql",
    "t": "2024 жылы ең аз жалақы алған 10 ойыншыны табыңыз. Жалақы бойынша өсу ретімен; жалақы тең болса - аты, сосын тегі бойынша әліпби ретімен; аты-жөні де бірдей болса - ойыншы id бойынша. Үш баған: аты, тегі, жалақысы.",
    "ref": "SELECT \"first_name\", \"last_name\", \"salary\" FROM \"players\" JOIN \"salaries\" ON \"salaries\".\"player_id\" = \"players\".\"id\" WHERE \"salaries\".\"year\" = 2024 ORDER BY \"salary\", \"first_name\", \"last_name\", \"players\".\"id\" LIMIT 10;"
   },
   {
    "f": "5.sql",
    "t": "Дәулет Нұрмағамбетов қай клубтарда ойнады? Бір баған: клуб атауы.",
    "ref": "SELECT DISTINCT \"name\" FROM \"teams\" WHERE \"id\" IN (SELECT \"team_id\" FROM \"performances\" WHERE \"player_id\" = (SELECT \"id\" FROM \"players\" WHERE \"first_name\" = 'Дәулет' AND \"last_name\" = 'Нұрмағамбетов'));"
   },
   {
    "f": "6.sql",
    "t": "2024 жылы қақпаға соққылардың (SOT) жалпы саны бойынша ең жақсы 3 клубты табыңыз. Бағанды «total shots on target» деп атаңыз, мәні кему ретімен. Екі баған: клуб атауы және соққылар саны.",
    "ref": "SELECT \"teams\".\"name\", SUM(\"SOT\") AS \"total shots on target\" FROM \"performances\" JOIN \"teams\" ON \"teams\".\"id\" = \"performances\".\"team_id\" WHERE \"performances\".\"year\" = 2024 GROUP BY \"teams\".\"id\" ORDER BY \"total shots on target\" DESC LIMIT 3;"
   },
   {
    "f": "7.sql",
    "t": "Бүкіл тарихтағы ең жоғары жалақы алған ойыншының аты-жөнін табыңыз. Екі баған: аты және тегі.",
    "ref": "SELECT \"first_name\", \"last_name\" FROM \"players\" WHERE \"id\" = (SELECT \"player_id\" FROM \"salaries\" ORDER BY \"salary\" DESC LIMIT 1);"
   },
   {
    "f": "8.sql",
    "t": "2024 жылы ең көп гол соққан ойыншының 2024 жылғы жалақысын табыңыз. Бір баған: жалақы.",
    "ref": "SELECT \"salary\" FROM \"salaries\" WHERE \"year\" = 2024 AND \"player_id\" = (SELECT \"player_id\" FROM \"performances\" WHERE \"year\" = 2024 ORDER BY \"GL\" DESC LIMIT 1);"
   },
   {
    "f": "9.sql",
    "t": "2024 жылы орташа жалақысы ең төмен 3 клубты табыңыз. Орташа жалақыны екі таңбаға дейін дөңгелектеп, «average salary» деп атаңыз; өсу ретімен. Екі баған: клуб атауы және орташа жалақы.",
    "ref": "SELECT \"teams\".\"name\", ROUND(AVG(\"salary\"), 2) AS \"average salary\" FROM \"salaries\" JOIN \"teams\" ON \"teams\".\"id\" = \"salaries\".\"team_id\" WHERE \"salaries\".\"year\" = 2024 GROUP BY \"teams\".\"id\" ORDER BY \"average salary\" LIMIT 3;"
   },
   {
    "f": "10.sql",
    "t": "Есеп: әр ойыншының аты, тегі, жалақысы, жылы және сол жылғы голдары (GL). Бес баған осы ретпен: first_name, last_name, salary, year, GL. Алдымен ойыншы id бойынша (өсу), ойыншы ішінде жыл бойынша кему, жыл тең болса голдар (кему), сосын жалақы (кему). Жалақы мен орындалу жылдары сәйкес болсын.",
    "ref": "SELECT \"first_name\", \"last_name\", \"salary\", \"salaries\".\"year\", \"GL\" FROM \"players\" JOIN \"salaries\" ON \"salaries\".\"player_id\" = \"players\".\"id\" JOIN \"performances\" ON \"performances\".\"player_id\" = \"players\".\"id\" AND \"performances\".\"year\" = \"salaries\".\"year\" ORDER BY \"players\".\"id\", \"salaries\".\"year\" DESC, \"GL\" DESC, \"salary\" DESC;"
   },
   {
    "f": "11.sql",
    "t": "2024 жылы бір қақпаға соққы үшін ең арзан 10 ойыншыны табыңыз. жалақыны SOT санына бөліңіз (қарапайым бөлу: SQLite-та бүтін санды бөлу бүтін сан береді). SOT = 0 болатындарды алып тастаңыз. Өсу ретімен; тең болса - аты, сосын тегі. Үш баған: аты, тегі, «salary per shot».",
    "ref": "SELECT \"first_name\", \"last_name\", \"salary\" / \"SOT\" AS \"salary per shot\" FROM \"players\" JOIN \"salaries\" ON \"salaries\".\"player_id\" = \"players\".\"id\" JOIN \"performances\" ON \"performances\".\"player_id\" = \"players\".\"id\" AND \"performances\".\"year\" = \"salaries\".\"year\" WHERE \"salaries\".\"year\" = 2024 AND \"SOT\" > 0 ORDER BY \"salary per shot\", \"first_name\", \"last_name\" LIMIT 10;"
   },
   {
    "f": "12.sql",
    "t": "2024 жылы бір қақпаға соққы үшін ең арзан 10 ойыншының ішінде және бір голдық пас (AST) үшін ең арзан 10 ойыншының ішінде бір мезгілде болатындарды табыңыз. Қарапайым бөлуді қолданыңыз (11.sql сияқты), AST = 0 болатындарды алып тастаңыз. Екі баған: аты және тегі; ойыншы id бойынша өсу ретімен.",
    "ref": "SELECT \"first_name\", \"last_name\" FROM \"players\" WHERE \"id\" IN (SELECT \"players\".\"id\" FROM \"players\" JOIN \"salaries\" ON \"salaries\".\"player_id\" = \"players\".\"id\" JOIN \"performances\" ON \"performances\".\"player_id\" = \"players\".\"id\" AND \"performances\".\"year\" = \"salaries\".\"year\" WHERE \"salaries\".\"year\" = 2024 AND \"SOT\" > 0 ORDER BY \"salary\" / \"SOT\", \"first_name\", \"last_name\" LIMIT 10) AND \"id\" IN (SELECT \"players\".\"id\" FROM \"players\" JOIN \"salaries\" ON \"salaries\".\"player_id\" = \"players\".\"id\" JOIN \"performances\" ON \"performances\".\"player_id\" = \"players\".\"id\" AND \"performances\".\"year\" = \"salaries\".\"year\" WHERE \"salaries\".\"year\" = 2024 AND \"AST\" > 0 ORDER BY \"salary\" / \"AST\", \"first_name\", \"last_name\" LIMIT 10) ORDER BY \"id\";"
   }
  ]
 },
 "sql1-dese": {
  "db": "mektep",
  "note": "Бұл - сайттың өз жаттығуы, ресми DESE тапсырмасы емес: Қазақстанның қалалары мен мектеп округтері туралы ойдан шығарылған дерекқор (mektep.db: districts, schools, graduation_rates, expenditures, staff_evaluations). Типтері: «Мемлекеттік» және «Жеке меншік». Жабылған округтердің аты «(жабық)» деп аяқталады. id-лерді қолмен жазбаңыз.",
  "tasks": [
   {
    "f": "1.sql",
    "t": "Картаға жазу үшін барлық мемлекеттік мектептердің атауы мен қаласын табыңыз («Мемлекеттік» типі). Екі баған: name, city.",
    "ref": "SELECT \"name\", \"city\" FROM \"schools\" WHERE \"type\" = 'Мемлекеттік';"
   },
   {
    "f": "2.sql",
    "t": "Жабылған (қазір жұмыс істемейтін) округтердің атауларын табыңыз: аты «(жабық)» деп аяқталады. Бір баған.",
    "ref": "SELECT \"name\" FROM \"districts\" WHERE \"name\" LIKE '%(жабық)';"
   },
   {
    "f": "3.sql",
    "t": "Округтердің оқушы басына орташа шығынының орташасын табыңыз (барлық округ тең салмақпен). Бағанды «Average District Per-Pupil Expenditure» деп атаңыз.",
    "ref": "SELECT AVG(\"per_pupil_expenditure\") AS \"Average District Per-Pupil Expenditure\" FROM \"expenditures\";"
   },
   {
    "f": "4.sql",
    "t": "Мемлекеттік мектептері ең көп 5 қаланы табыңыз. Қала атауы мен мектеп саны; мектеп саны кему ретімен, тең болса - қала аты әліпби бойынша.",
    "ref": "SELECT \"city\", COUNT(*) FROM \"schools\" WHERE \"type\" = 'Мемлекеттік' GROUP BY \"city\" ORDER BY COUNT(*) DESC, \"city\" LIMIT 5;"
   },
   {
    "f": "5.sql",
    "t": "Мемлекеттік мектептер саны 3 немесе одан аз қалаларды табыңыз. Қала мен мектеп саны; мектеп саны кему ретімен, тең болса - қала аты бойынша.",
    "ref": "SELECT \"city\", COUNT(*) FROM \"schools\" WHERE \"type\" = 'Мемлекеттік' GROUP BY \"city\" HAVING COUNT(*) <= 3 ORDER BY COUNT(*) DESC, \"city\";"
   },
   {
    "f": "6.sql",
    "t": "Бітіру көрсеткіші 100% болған мектептердің (мемлекеттік не жеке) атауларын табыңыз. Бір баған.",
    "ref": "SELECT \"name\" FROM \"schools\" WHERE \"id\" IN (SELECT \"school_id\" FROM \"graduation_rates\" WHERE \"graduated\" = 100);"
   },
   {
    "f": "7.sql",
    "t": "Аты дәл «Бостандық» болатын округтегі мектептердің атауларын табыңыз (Алматыда «Бостандық гимназиялары» деген басқа округ те бар - оны қоспаңыз!). Бір баған.",
    "ref": "SELECT \"name\" FROM \"schools\" WHERE \"district_id\" = (SELECT \"id\" FROM \"districts\" WHERE \"name\" = 'Бостандық');"
   },
   {
    "f": "8.sql",
    "t": "Барлық округтердің атауы мен оқушылар санын көрсетіңіз. Екі баған: округ аты, pupils.",
    "ref": "SELECT \"name\", \"pupils\" FROM \"districts\" JOIN \"expenditures\" ON \"expenditures\".\"district_id\" = \"districts\".\"id\";"
   },
   {
    "f": "9.sql",
    "t": "Оқушы саны ең аз округтің (немесе округтердің) атауын табыңыз. Тек атау.",
    "ref": "SELECT \"name\" FROM \"districts\" WHERE \"id\" IN (SELECT \"district_id\" FROM \"expenditures\" WHERE \"pupils\" = (SELECT MIN(\"pupils\") FROM \"expenditures\"));"
   },
   {
    "f": "10.sql",
    "t": "Оқушы басына шығыны ең жоғары 5 мемлекеттік округті табыңыз («Мемлекеттік» типі). Екі баған: округ аты және оқушы басына шығын; шығын кему ретімен.",
    "ref": "SELECT \"name\", \"per_pupil_expenditure\" FROM \"districts\" JOIN \"expenditures\" ON \"expenditures\".\"district_id\" = \"districts\".\"id\" WHERE \"districts\".\"type\" = 'Мемлекеттік' ORDER BY \"per_pupil_expenditure\" DESC LIMIT 5;"
   },
   {
    "f": "11.sql",
    "t": "Мектеп атауларын, олардың оқушы басына шығынын (округтің шығынымен бірдей деп алыңыз) және бітіру көрсеткішін көрсетіңіз. Шығын кему ретімен, тең болса - мектеп аты бойынша. Үш баған: name, per_pupil_expenditure, graduated.",
    "ref": "SELECT \"schools\".\"name\", \"per_pupil_expenditure\", \"graduated\" FROM \"schools\" JOIN \"expenditures\" ON \"expenditures\".\"district_id\" = \"schools\".\"district_id\" JOIN \"graduation_rates\" ON \"graduation_rates\".\"school_id\" = \"schools\".\"id\" ORDER BY \"per_pupil_expenditure\" DESC, \"schools\".\"name\";"
   },
   {
    "f": "12.sql",
    "t": "Оқушы басына шығыны орташадан жоғары ЖӘНЕ «үлгілі» (exemplary) бағаланған мұғалімдердің үлесі орташадан жоғары мемлекеттік округтерді табыңыз. Үш баған: округ аты, шығын, exemplary. Алдымен exemplary бойынша кему, сосын шығын бойынша кему.",
    "ref": "SELECT \"name\", \"per_pupil_expenditure\", \"exemplary\" FROM \"districts\" JOIN \"expenditures\" ON \"expenditures\".\"district_id\" = \"districts\".\"id\" JOIN \"staff_evaluations\" ON \"staff_evaluations\".\"district_id\" = \"districts\".\"id\" WHERE \"districts\".\"type\" = 'Мемлекеттік' AND \"per_pupil_expenditure\" > (SELECT AVG(\"per_pupil_expenditure\") FROM \"expenditures\") AND \"exemplary\" > (SELECT AVG(\"exemplary\") FROM \"staff_evaluations\") ORDER BY \"exemplary\" DESC, \"per_pupil_expenditure\" DESC;"
   }
  ]
 },
 "sql1-packages": {
  "db": "pochta",
  "note": "Бұл - сайттың өз жаттығуы, ресми Packages, Please тапсырмасы емес: ойдан шығарылған пошта дерекқоры (pochta.db: addresses, drivers, packages, scans). Үш жұмбақты қадам-қадаммен шешіңіз. Бұл жерде жауапты тікелей табатын сұрауларды жазасыз; ресми тапсырмада log.sql мен answers.txt толтырасыз.",
  "tasks": [
   {
    "f": "1.sql",
    "t": "Лост хат: Ақеркенің «Абай даңғылы 15» мекенжайынан «Төле би көшесі 2» мекенжайына жіберілген пакеттің id-ін және мазмұнын табыңыз. Мекенжай id-лерін қолмен жазбаңыз. Екі баған: id, contents.",
    "ref": "SELECT \"id\", \"contents\" FROM \"packages\" WHERE \"from_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Абай даңғылы 15') AND \"to_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Төле би көшесі 2');"
   },
   {
    "f": "2.sql",
    "t": "Сол хаттың барлық сканерлеуін (scans) уақыт бойынша өсу ретімен көрсетіңіз: мекенжай (address), түрі (type), әрекет (action), уақыт (timestamp). Төрт баған осы ретпен.",
    "ref": "SELECT \"address\", \"type\", \"action\", \"timestamp\" FROM \"scans\" JOIN \"addresses\" ON \"addresses\".\"id\" = \"scans\".\"address_id\" WHERE \"package_id\" = (SELECT \"id\" FROM \"packages\" WHERE \"from_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Абай даңғылы 15') AND \"to_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Төле би көшесі 2')) ORDER BY \"timestamp\";"
   },
   {
    "f": "3.sql",
    "t": "Хат ақыры қай мекенжайға тапсырылды? Соңғы «Drop» сканерлеудің мекенжайы мен түрін табыңыз. Екі баған: address, type.",
    "ref": "SELECT \"address\", \"type\" FROM \"addresses\" WHERE \"id\" = (SELECT \"address_id\" FROM \"scans\" WHERE \"action\" = 'Drop' AND \"package_id\" = (SELECT \"id\" FROM \"packages\" WHERE \"from_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Абай даңғылы 15') AND \"to_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Төле би көшесі 2')) ORDER BY \"timestamp\" DESC LIMIT 1);"
   },
   {
    "f": "4.sql",
    "t": "Қулық сәлемдеме: «жіберуші мекенжайы» (from_address_id) жоқ, мазмұнында «үйрек» сөзі бар пакеттің id-ін табыңыз. Бір баған: id.",
    "ref": "SELECT \"id\" FROM \"packages\" WHERE \"from_address_id\" IS NULL AND \"contents\" LIKE '%үйрек%';"
   },
   {
    "f": "5.sql",
    "t": "Қулық сәлемдеме ақыры қай мекенжайға тапсырылды (соңғы «Drop»)? Мекенжай түрін (type) көрсетіңіз. Бір баған.",
    "ref": "SELECT \"type\" FROM \"addresses\" WHERE \"id\" = (SELECT \"address_id\" FROM \"scans\" WHERE \"action\" = 'Drop' AND \"package_id\" = (SELECT \"id\" FROM \"packages\" WHERE \"from_address_id\" IS NULL AND \"contents\" LIKE '%үйрек%') ORDER BY \"timestamp\" DESC LIMIT 1);"
   },
   {
    "f": "6.sql",
    "t": "Ұмытылған сыйлық: «Жібек жолы 109» мекенжайынан «Мұқағали көшесі 728» мекенжайына жіберілген пакеттердің ішінен соңғы сканерлеуі «Pick» болып қалған (тапсырылмаған) пакеттің мазмұнын табыңыз. Бір баған: contents. Кеңес: екі пакет бар, біреуі жеткен.",
    "ref": "SELECT \"contents\" FROM \"packages\" WHERE \"from_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Жібек жолы 109') AND \"to_address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Мұқағали көшесі 728') AND \"id\" NOT IN (SELECT \"package_id\" FROM \"scans\" WHERE \"action\" = 'Drop' AND \"address_id\" = (SELECT \"id\" FROM \"addresses\" WHERE \"address\" = 'Мұқағали көшесі 728'));"
   },
   {
    "f": "7.sql",
    "t": "Сол сыйлық қазір кімнің қолында? Пакеттің ең соңғы сканерлеуін жасаған жүргізушінің атын табыңыз. Бір баған: name.",
    "ref": "SELECT \"name\" FROM \"drivers\" WHERE \"id\" = (SELECT \"driver_id\" FROM \"scans\" WHERE \"package_id\" = (SELECT \"id\" FROM \"packages\" WHERE \"contents\" = 'Сурет кітабы') ORDER BY \"timestamp\" DESC LIMIT 1);"
   }
  ]
 }
});
